//! Fixture writers: synthetic files in the game's formats, generated by our
//! own code so tests never need game data.
//!
//! Each format module (M1) provides one or more [`FixtureWriter`]s and adds
//! them to [`registry`]. The `glasnost-fixtures` tool (crate `tools`) writes
//! the registry's output plus a [`manifest`]; `cargo xtask check` regenerates
//! the fixtures and rejects any committed fixture file that our writers do not
//! reproduce byte for byte.
//!
//! Parsers are tested with [`check_round_trip`]: write a value, parse it back,
//! compare.

use std::collections::BTreeMap;
use std::fmt::Debug;

/// Name of the manifest file at the root of a fixture directory.
pub const MANIFEST_FILE: &str = "FIXTURES.manifest";

/// A deterministic writer for one synthetic fixture file.
pub trait FixtureWriter {
    /// Short, lowercase format tag used as the directory name, e.g. `"pal"`.
    fn format(&self) -> &'static str;
    /// File stem within the format directory, e.g. `"ramps-tint0"`.
    fn name(&self) -> String;
    /// File extension without the dot.
    fn extension(&self) -> &'static str;
    /// Appends the fixture's bytes to `out`. Must depend only on `self`.
    fn write(&self, out: &mut Vec<u8>);
}

/// One generated fixture file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Fixture {
    /// Path relative to the fixture root, always with `/` separators.
    pub path: String,
    /// File contents.
    pub bytes: Vec<u8>,
}

/// Every fixture writer in the crate, one `extend` per format module.
pub fn registry() -> Vec<Box<dyn FixtureWriter>> {
    let mut w: Vec<Box<dyn FixtureWriter>> = Vec::new();
    w.extend(crate::mix::fixture_writers());
    w.extend(crate::pal::fixture_writers());
    w.extend(crate::shp::fixture_writers());
    w.extend(crate::tmp::fixture_writers());
    w.extend(crate::pcx::fixture_writers());
    w.extend(crate::csf::fixture_writers());
    w.extend(crate::vxl::fixture_writers());
    w.extend(crate::hva::fixture_writers());
    w.extend(crate::aud::fixture_writers());
    w.extend(crate::idx::fixture_writers());
    w.extend(crate::lzo::fixture_writers());
    w.extend(crate::lcw::fixture_writers());
    w.extend(crate::mappack::fixture_writers());
    w
}

/// Error from [`generate`]: two writers produced the same path.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DuplicatePath(pub String);

impl std::fmt::Display for DuplicatePath {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "two fixture writers produce {}", self.0)
    }
}

impl std::error::Error for DuplicatePath {}

/// Runs `writers` and returns their fixtures sorted by path.
pub fn generate(writers: &[Box<dyn FixtureWriter>]) -> Result<Vec<Fixture>, DuplicatePath> {
    let mut out = BTreeMap::new();
    for w in writers {
        let path = format!("{}/{}.{}", w.format(), w.name(), w.extension());
        let mut bytes = Vec::new();
        w.write(&mut bytes);
        if out.insert(path.clone(), bytes).is_some() {
            return Err(DuplicatePath(path));
        }
    }
    Ok(out
        .into_iter()
        .map(|(path, bytes)| Fixture { path, bytes })
        .collect())
}

/// 64-bit FNV-1a, used to fingerprint fixtures in the manifest. Not a
/// security hash: the manifest only detects drift.
pub fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xCBF2_9CE4_8422_2325;
    for &b in bytes {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01B3);
    }
    h
}

/// The manifest text for `fixtures`: a header, then one line per file with
/// fingerprint, length and path.
pub fn manifest(fixtures: &[Fixture]) -> String {
    let mut s = String::from(
        "# SPDX-License-Identifier: CC0-1.0\n\
         # glasnost-synthetic: generated by our own fixture writers (glasnost-fmt).\n\
         # Do not edit; regenerate with `cargo run -p glasnost-tools --bin glasnost-fixtures`.\n",
    );
    for f in fixtures {
        s.push_str(&format!(
            "{:016x} {:>8} {}\n",
            fnv1a64(&f.bytes),
            f.bytes.len(),
            f.path
        ));
    }
    s
}

/// A parser paired with its writer.
pub trait Codec {
    /// Decoded form.
    type Value: PartialEq + Debug;
    /// Parse error.
    type Error: Debug;
    /// Parses bytes.
    fn decode(bytes: &[u8]) -> Result<Self::Value, Self::Error>;
    /// Serialises a value.
    fn encode(value: &Self::Value) -> Vec<u8>;
}

/// Failure of [`check_round_trip`].
#[derive(Debug)]
pub enum RoundTripError<E> {
    /// The encoded bytes did not parse.
    Decode(E),
    /// They parsed to a different value.
    Mismatch,
    /// Re-encoding the parsed value gave different bytes.
    NotCanonical,
}

/// Encodes `value`, decodes it, and checks that both the value and a second
/// encoding come back unchanged.
pub fn check_round_trip<C: Codec>(value: &C::Value) -> Result<(), RoundTripError<C::Error>> {
    let bytes = C::encode(value);
    let parsed = C::decode(&bytes).map_err(RoundTripError::Decode)?;
    if &parsed != value {
        return Err(RoundTripError::Mismatch);
    }
    if C::encode(&parsed) != bytes {
        return Err(RoundTripError::NotCanonical);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::synth::SynthRng;

    /// A toy length-prefixed blob format, used only to exercise the harness.
    struct Blob;

    impl Codec for Blob {
        type Value = Vec<u8>;
        type Error = &'static str;
        fn decode(bytes: &[u8]) -> Result<Vec<u8>, &'static str> {
            let (len, rest) = bytes.split_first().ok_or("empty")?;
            if rest.len() != usize::from(*len) {
                return Err("length mismatch");
            }
            Ok(rest.to_vec())
        }
        fn encode(value: &Vec<u8>) -> Vec<u8> {
            let mut out = vec![u8::try_from(value.len()).expect("toy format holds < 256 bytes")];
            out.extend_from_slice(value);
            out
        }
    }

    struct BlobWriter {
        seed: u64,
    }

    impl FixtureWriter for BlobWriter {
        fn format(&self) -> &'static str {
            "blob"
        }
        fn name(&self) -> String {
            format!("seed{}", self.seed)
        }
        fn extension(&self) -> &'static str {
            "bin"
        }
        fn write(&self, out: &mut Vec<u8>) {
            let mut data = vec![0u8; 24];
            SynthRng::new(self.seed).fill(&mut data);
            out.extend(Blob::encode(&data));
        }
    }

    #[test]
    fn round_trip_harness_accepts_a_correct_codec() {
        let mut data = vec![0u8; 40];
        SynthRng::new(1).fill(&mut data);
        check_round_trip::<Blob>(&data).unwrap();
    }

    #[test]
    fn generation_is_sorted_and_deterministic() {
        let writers: Vec<Box<dyn FixtureWriter>> = vec![
            Box::new(BlobWriter { seed: 9 }),
            Box::new(BlobWriter { seed: 2 }),
        ];
        let a = generate(&writers).unwrap();
        let b = generate(&writers).unwrap();
        assert_eq!(a, b);
        assert_eq!(a[0].path, "blob/seed2.bin");
        assert_eq!(manifest(&a), manifest(&b));
        assert!(manifest(&a).lines().any(|l| l.ends_with(" blob/seed9.bin")));
    }

    #[test]
    fn duplicate_paths_are_rejected() {
        let writers: Vec<Box<dyn FixtureWriter>> = vec![
            Box::new(BlobWriter { seed: 4 }),
            Box::new(BlobWriter { seed: 4 }),
        ];
        assert_eq!(
            generate(&writers),
            Err(DuplicatePath("blob/seed4.bin".into()))
        );
    }

    #[test]
    fn fnv_matches_reference_vectors() {
        // Published FNV-1a 64 test vectors.
        assert_eq!(fnv1a64(b""), 0xcbf2_9ce4_8422_2325);
        assert_eq!(fnv1a64(b"a"), 0xaf63_dc4c_8601_ec8c);
    }
}
